@@ -0,0 +1,33 @@
+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { consume } from "./batches.js";
+import { t } from "../i18n/messages.js";
+
+/** Imports validated sale rows atomically, skipping previously imported tickets. */
+export function importSales(store, rows) {
+  const work = memoryStore(store.data);
+  const known = new Set(work.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    try {
+      const dish = getDish(work, row.dishId);
+      const ingredients = scaled(getRecipe(work, dish.recipeId), row.qty);
+      if (known.has(row.ticket)) continue;
+      for (const ingredient of ingredients) {
+        if (ingredient.qty === 0) continue;
+        consume(work, ingredient.itemId, ingredient.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      }
+      work.data.sales.push({ id: work.nextId("sale"), ticket: row.ticket, soldAt: row.soldAt, dishId: row.dishId, qty: row.qty, ingredients });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("sales_row", { row: row.row, reason: t(error.code, "en", error.params) });
+    }
+  }
+  store.data = work.data;
+  return { tickets: tickets.size, dishes };
+}
